    commander: String(st.players?.[mySide]?.commanderId || ""),
    battles: 1,
    wins: 0,
    creaturesPlayed: 0,
    cardsByFaction: { goblins: 0, gnomes: 0, dwarves: 0 },
    cost7Plays: 0,
    hitsLanded: 0,
    hitsBlocked: 0,
    unitsDefeated: 0,
    commanderDamage: 0,
    mineHoldTurns: 0,
    minerMines: 0
